const std = @import("std");
const chars = @import("charset.zig");
const code = @import("compiler.zig");
pub const Captures = [42]i16;
pub const empty: Captures = @splat(-1);
pub const Result = struct { captures: Captures, q: usize };
const State = struct { p: usize, q: usize, captures: Captures, visited: std.StaticBitSet(300) = std.StaticBitSet(300).initEmpty() };
pub fn consumes(ins: code.Instruction, text: []const u8, q: usize, flags: []const u8) bool {
    if (q >= text.len) return false;
    return switch (ins.op) { .CHAR => chars.same(text[q], @intCast(ins.x), flags), .ANY => text[q] != 10 or std.mem.indexOfScalar(u8, flags, 's') != null, .CLASS => chars.class(ins.set, ins.neg, text[q], flags), else => false };
}
pub const VM = struct {
    a: std.mem.Allocator, program: []const code.Instruction, flags: []const u8, text: []const u8, full: bool, steps: usize = 0,
    pub fn run(vm: *VM, p: usize, q: usize, captures: Captures, partial: bool) anyerror!?Result {
        var stack: std.ArrayList(State) = .empty;
        defer stack.deinit(vm.a);
        try stack.append(vm.a, .{ .p = p, .q = q, .captures = captures });
        while (stack.items.len > 0) {
            var s = stack.pop().?;
            while (true) {
                vm.steps += 1; if (vm.steps > 200000) return error.TooManySteps;
                const ins = vm.program[s.p];
                switch (ins.op) {
                    .CHAR, .ANY, .CLASS => { if (!consumes(ins, vm.text, s.q, vm.flags)) break; s.q += 1; s.p += 1; s.visited = .initEmpty(); },
                    .SPLIT => { if (s.visited.isSet(s.p)) break; s.visited.set(s.p); var alternate = s; alternate.p = ins.y; try stack.append(vm.a, alternate); s.p = ins.x; },
                    .JMP => s.p = ins.x,
                    .SAVE => { s.captures[ins.x] = @intCast(s.q); s.p += 1; },
                    .ASSERT => { if (!chars.assertion(ins.assertion, vm.text, s.q, vm.flags)) break; s.p += 1; },
                    .BACKREF => {
                        const first = s.captures[2 * ins.x]; const last = s.captures[2 * ins.x + 1];
                        if (first < 0 or last < first) break;
                        const start: usize = @intCast(first); const count: usize = @intCast(last - first);
                        if (s.q + count > vm.text.len) break;
                        var valid = true; for (0..count) |j| if (!chars.same(vm.text[start + j], vm.text[s.q + j], vm.flags)) { valid = false; break; };
                        if (!valid) break; s.q += count; s.p += 1; if (count > 0) s.visited = .initEmpty();
                    },
                    .LOOK => {
                        const found = try vm.run(s.p + 1, s.q, s.captures, true);
                        if (ins.look == .NOT) { if (found != null) break; } else {
                            const result = found orelse break; s.captures = result.captures;
                            if (ins.look == .ATOMIC) { if (result.q > s.q) s.visited = .initEmpty(); s.q = result.q; }
                        }
                        s.p = ins.x;
                    },
                    .MATCH => { if (partial or !vm.full or s.q == vm.text.len) return .{ .captures = s.captures, .q = s.q }; break; },
                }
            }
        }
        return null;
    }
    pub fn search(vm: *VM, start: usize) !?Captures {
        var b = if (vm.full) 0 else start;
        while (b <= vm.text.len) : (b += 1) { if (try vm.run(0, b, empty, false)) |r| return r.captures; if (vm.full) break; }
        return null;
    }
};

const std = @import("std");
pub const Set = std.StaticBitSet(128);
pub fn word(c: u8) bool { return std.ascii.isAlphanumeric(c) or c == '_'; }
pub fn switched(c: u8) u8 { return if (std.ascii.isLower(c)) std.ascii.toUpper(c) else if (std.ascii.isUpper(c)) std.ascii.toLower(c) else c; }
pub fn standard(c: u8) Set {
    var s = Set.initEmpty();
    for (0..128) |n| {
        const x: u8 = @intCast(n);
        const yes = switch (std.ascii.toLower(c)) { 'd' => std.ascii.isDigit(x), 'w' => word(x), 's' => x == 9 or x == 10 or x == 11 or x == 12 or x == 13 or x == 32, else => false };
        if (yes) s.set(n);
    }
    return s;
}
pub fn same(a: u8, b: u8, flags: []const u8) bool { return a == b or (std.mem.indexOfScalar(u8, flags, 'i') != null and std.ascii.toLower(a) == std.ascii.toLower(b)); }
pub fn class(s: Set, neg: bool, c: u8, flags: []const u8) bool {
    const yes = s.isSet(c) or (std.mem.indexOfScalar(u8, flags, 'i') != null and s.isSet(switched(c)));
    return yes != neg;
}
pub const Assertion = enum { BOL, EOL, WORD, NOTWORD };
pub fn assertion(kind: Assertion, text: []const u8, q: usize, flags: []const u8) bool {
    const multiline = std.mem.indexOfScalar(u8, flags, 'm') != null;
    const before = q > 0 and word(text[q - 1]);
    const after = q < text.len and word(text[q]);
    return switch (kind) { .BOL => q == 0 or (multiline and text[q - 1] == '\n'), .EOL => q == text.len or (multiline and text[q] == '\n'), .WORD => before != after, .NOTWORD => before == after };
}

const std = @import("std");
const chars = @import("charset.zig");
pub const Node = struct {
    kind: enum { literal, any, class, assertion, backref, group, look, concat, alternation, repeat },
    value: usize = 0, set: chars.Set = chars.Set.initEmpty(), neg: bool = false,
    children: []*Node = &.{}, child: ?*Node = null, lower: usize = 0, upper: ?usize = null,
    mode: enum { greedy, lazy, possessive } = .greedy, name: ?[]const u8 = null, column: usize = 0,
};
pub const Op = enum { CHAR, ANY, CLASS, SPLIT, JMP, SAVE, ASSERT, BACKREF, LOOK, MATCH };
pub const Look = enum { AHEAD, NOT, ATOMIC };
pub const Instruction = struct { op: Op, x: usize = 0, y: usize = 0, set: chars.Set = chars.Set.initEmpty(), neg: bool = false, assertion: chars.Assertion = .BOL, look: Look = .AHEAD };
pub const Builder = struct {
    a: std.mem.Allocator, instructions: std.ArrayList(Instruction) = .empty,
    fn emit(b: *Builder, ins: Instruction) !usize { const p = b.instructions.items.len; try b.instructions.append(b.a, ins); return p; }
    pub fn node(b: *Builder, n: *const Node) anyerror!void {
        switch (n.kind) {
            .literal => { _ = try b.emit(.{ .op = .CHAR, .x = n.value }); },
            .any => { _ = try b.emit(.{ .op = .ANY }); },
            .class => { _ = try b.emit(.{ .op = .CLASS, .set = n.set, .neg = n.neg }); },
            .assertion => { _ = try b.emit(.{ .op = .ASSERT, .assertion = @enumFromInt(n.value) }); },
            .backref => { _ = try b.emit(.{ .op = .BACKREF, .x = n.value }); },
            .group => { _ = try b.emit(.{ .op = .SAVE, .x = 2 * n.value }); try b.node(n.child.?); _ = try b.emit(.{ .op = .SAVE, .x = 2 * n.value + 1 }); },
            .look => { const p = try b.emit(.{ .op = .LOOK, .look = if (n.neg) .NOT else .AHEAD }); try b.node(n.child.?); _ = try b.emit(.{ .op = .MATCH }); b.instructions.items[p].x = b.instructions.items.len; },
            .concat => for (n.children) |c| try b.node(c),
            .alternation => {
                var jumps: std.ArrayList(usize) = .empty;
                for (n.children[0..n.children.len - 1]) |c| {
                    const p = try b.emit(.{ .op = .SPLIT, .x = b.instructions.items.len + 1 });
                    try b.node(c); try jumps.append(b.a, try b.emit(.{ .op = .JMP })); b.instructions.items[p].y = b.instructions.items.len;
                }
                try b.node(n.children[n.children.len - 1]);
                for (jumps.items) |p| b.instructions.items[p].x = b.instructions.items.len;
            },
            .repeat => {
                if (n.mode == .possessive) {
                    const p = try b.emit(.{ .op = .LOOK, .look = .ATOMIC });
                    var copy = n.*; copy.mode = .greedy; try b.node(&copy);
                    _ = try b.emit(.{ .op = .MATCH }); b.instructions.items[p].x = b.instructions.items.len; return;
                }
                if (n.upper == null and n.lower == 0) {
                    const p = try b.emit(.{ .op = .SPLIT }); const next = b.instructions.items.len;
                    try b.node(n.child.?); _ = try b.emit(.{ .op = .JMP, .x = p }); b.split(p, next, b.instructions.items.len, n.mode == .lazy);
                } else if (n.upper == null) {
                    for (0..n.lower - 1) |_| try b.node(n.child.?);
                    const first = b.instructions.items.len; try b.node(n.child.?); const p = try b.emit(.{ .op = .SPLIT }); b.split(p, first, b.instructions.items.len, n.mode == .lazy);
                } else {
                    for (0..n.lower) |_| try b.node(n.child.?);
                    var optional: std.ArrayList(usize) = .empty;
                    for (n.lower..n.upper.?) |_| { const p = try b.emit(.{ .op = .SPLIT }); try optional.append(b.a, p); try b.node(n.child.?); }
                    for (optional.items) |p| b.split(p, p + 1, b.instructions.items.len, n.mode == .lazy);
                }
            },
        }
    }
    fn split(b: *Builder, p: usize, yes: usize, no: usize, lazy: bool) void { b.instructions.items[p].x = if (lazy) no else yes; b.instructions.items[p].y = if (lazy) yes else no; }
    pub fn compile(b: *Builder, root: *Node) ![]const Instruction { _ = try b.emit(.{ .op = .SAVE }); try b.node(root); _ = try b.emit(.{ .op = .SAVE, .x = 1 }); _ = try b.emit(.{ .op = .MATCH }); return b.instructions.items; }
};
pub const Properties = struct { min: usize = 0, max: ?usize = 0, first: chars.Set = chars.Set.initEmpty(), nullable: bool = true };
pub fn properties(n: *const Node, flags: []const u8) Properties {
    var p: Properties = .{};
    switch (n.kind) {
        .literal, .any, .class => {
            p.min = 1; p.max = 1; p.nullable = false;
            for (0..128) |x| { const c: u8 = @intCast(x); if (switch (n.kind) { .literal => chars.same(c, @intCast(n.value), flags), .any => c != 10 or std.mem.indexOfScalar(u8, flags, 's') != null, .class => chars.class(n.set, n.neg, c, flags), else => false }) p.first.set(x); }
        },
        .assertion, .look => {},
        .backref => { p.max = null; p.first = chars.Set.initFull(); },
        .group => return properties(n.child.?, flags),
        .repeat => { p = properties(n.child.?, flags); p.min *= n.lower; p.max = if (p.max == 0) 0 else if (p.max == null or n.upper == null) null else p.max.? * n.upper.?; if (n.upper == 0) p.first = chars.Set.initEmpty(); p.nullable = n.lower == 0 or n.upper == 0 or p.nullable; },
        .concat => for (n.children) |c| { const v = properties(c, flags); p.min += v.min; p.max = if (p.max != null and v.max != null) p.max.? + v.max.? else null; if (p.nullable) { p.first.setUnion(v.first); p.nullable = v.nullable; } },
        .alternation => { p.min = std.math.maxInt(usize); p.nullable = false; for (n.children) |c| { const v = properties(c, flags); p.min = @min(p.min, v.min); p.max = if (p.max != null and v.max != null) @max(p.max.?, v.max.?) else null; p.first.setUnion(v.first); p.nullable = p.nullable or v.nullable; } },
    }
    return p;
}

const std = @import("std");
const chars = @import("charset.zig");
const code = @import("compiler.zig");
pub const Buffer = struct {
    a: std.mem.Allocator, data: std.ArrayList(u8) = .empty,
    pub fn add(b: *Buffer, s: []const u8) !void { try b.data.appendSlice(b.a, s); }
    pub fn print(b: *Buffer, comptime fmt: []const u8, args: anytype) !void { try b.add(try std.fmt.allocPrint(b.a, fmt, args)); }
    pub fn line(b: *Buffer, s: []const u8) !void { try b.add(s); try b.add("\n"); }
};
pub fn quoted(a: std.mem.Allocator, text: []const u8) ![]const u8 {
    var b: Buffer = .{ .a = a }; try b.add("\"");
    for (text) |c| switch (c) { '\\' => try b.add("\\\\"), '"' => try b.add("\\\""), 10 => try b.add("\\n"), 9 => try b.add("\\t"), else => try b.data.append(a, c) };
    try b.add("\""); return b.data.items;
}
pub fn decode(a: std.mem.Allocator, text: []const u8) ![]const u8 {
    var b: std.ArrayList(u8) = .empty; var p: usize = 1;
    while (p + 1 < text.len) : (p += 1) { var c = text[p]; if (c == '\\') { p += 1; c = switch (text[p]) { 'n' => 10, 't' => 9, else => text[p] }; } try b.append(a, c); }
    return b.items;
}
pub fn character(a: std.mem.Allocator, c: usize) ![]const u8 {
    if (c >= 33 and c <= 126 and c != '\\' and c != ']' and c != '^' and c != '-') { const s = try a.alloc(u8, 1); s[0] = @intCast(c); return s; }
    return std.fmt.allocPrint(a, "\\x{X:0>2}", .{c});
}
pub fn set(a: std.mem.Allocator, s: chars.Set, neg: bool) ![]const u8 {
    var b: Buffer = .{ .a = a }; try b.add(if (neg) "[^" else "["); var p: usize = 0;
    while (p < 128) { if (!s.isSet(p)) { p += 1; continue; } const start = p; while (p + 1 < 128 and s.isSet(p + 1)) p += 1; try b.add(try character(a, start)); if (p > start) { if (p > start + 1) try b.add("-"); try b.add(try character(a, p)); } p += 1; }
    try b.add("]"); return b.data.items;
}
pub fn instruction(a: std.mem.Allocator, ins: code.Instruction) ![]const u8 {
    return switch (ins.op) {
        .CHAR => std.fmt.allocPrint(a, "CHAR {s}", .{try character(a, ins.x)}),
        .ANY => "ANY", .CLASS => std.fmt.allocPrint(a, "CLASS {s}", .{try set(a, ins.set, ins.neg)}),
        .SPLIT => std.fmt.allocPrint(a, "SPLIT {d}, {d}", .{ins.x, ins.y}),
        .JMP, .SAVE, .BACKREF => std.fmt.allocPrint(a, "{s} {d}", .{@tagName(ins.op), ins.x}),
        .ASSERT => std.fmt.allocPrint(a, "ASSERT {s}", .{@tagName(ins.assertion)}),
        .LOOK => std.fmt.allocPrint(a, "LOOK {s} {d}", .{@tagName(ins.look), ins.x}), .MATCH => "MATCH",
    };
}

const std = @import("std");
const chars = @import("charset.zig");
const code = @import("compiler.zig");
const fmt = @import("formatter.zig");
const back = @import("backtrack_vm.zig");
const pike = @import("pike_vm.zig");
const Text = []const u8;
const Name = struct { name: Text, group: usize };
const Pattern = struct { name: Text, flags: Text, text: Text, groups: usize = 0, names: []const Name = &.{}, root: ?*code.Node = null, program: []const code.Instruction = &.{}, compatible: bool = true, message: ?Text = null, column: usize = 0 };
const Parser = struct {
    a: std.mem.Allocator, text: Text, p: usize = 0, groups: usize = 0, names: std.ArrayList(Name) = .empty, refs: std.ArrayList(*code.Node) = .empty, message: Text = "", column: usize = 0,
    fn peek(p: *Parser) u8 { return if (p.p < p.text.len) p.text[p.p] else 0; }
    fn fail(p: *Parser, message: Text, column: usize) error{InvalidPattern} { p.message = message; p.column = column; return error.InvalidPattern; }
    fn node(p: *Parser, n: code.Node) !*code.Node { const result = try p.a.create(code.Node); result.* = n; return result; }
    fn digits(p: *Parser) Text { const start = p.p; while (std.ascii.isDigit(p.peek())) p.p += 1; return p.text[start..p.p]; }
    fn name(p: *Parser) !Text {
        if (!std.ascii.isAlphabetic(p.peek()) and p.peek() != '_') return p.fail("invalid group name", p.p + 1);
        const start = p.p; while (std.ascii.isAlphanumeric(p.peek()) or p.peek() == '_') p.p += 1;
        if (p.peek() != '>') return p.fail("invalid group name", p.p + 1);
        const value = p.text[start..p.p]; p.p += 1; return value;
    }
    fn alternate(p: *Parser) anyerror!*code.Node {
        var list: std.ArrayList(*code.Node) = .empty; try list.append(p.a, try p.concat());
        while (p.peek() == '|') { p.p += 1; try list.append(p.a, try p.concat()); }
        return if (list.items.len == 1) list.items[0] else p.node(.{ .kind = .alternation, .children = list.items });
    }
    fn concat(p: *Parser) anyerror!*code.Node {
        var list: std.ArrayList(*code.Node) = .empty;
        while (p.peek() != 0 and p.peek() != '|' and p.peek() != ')') try list.append(p.a, try p.quantified());
        return if (list.items.len == 1) list.items[0] else p.node(.{ .kind = .concat, .children = list.items });
    }
    fn quantifier(c: u8) bool { return c == '*' or c == '+' or c == '?' or c == '{'; }
    fn quantified(p: *Parser) anyerror!*code.Node {
        if (quantifier(p.peek())) return p.fail("nothing to repeat", p.p + 1);
        const base = try p.element(); if (!quantifier(p.peek())) return base;
        if (base.kind == .assertion or base.kind == .look) return p.fail("nothing to repeat", p.p + 1);
        const column = p.p + 1; const c = p.peek(); p.p += 1; var lower: usize = 0; var upper: ?usize = null;
        switch (c) {
            '*' => {}, '+' => lower = 1, '?' => upper = 1,
            else => {
                const low_digits = p.digits(); if (low_digits.len == 0) return p.fail("invalid quantifier", column); lower = try std.fmt.parseInt(usize, low_digits, 10);
                if (p.peek() == '}') upper = lower else if (p.peek() == ',') { p.p += 1; if (p.peek() != '}') { const high = p.digits(); if (high.len == 0) return p.fail("invalid quantifier", column); upper = try std.fmt.parseInt(usize, high, 10); } } else return p.fail("invalid quantifier", column);
                if (p.peek() != '}') return p.fail("invalid quantifier", column); p.p += 1;
                if (lower > 100 or (upper != null and upper.? > 100)) return p.fail("quantifier too large", column);
                if (upper != null and lower > upper.?) return p.fail("quantifier range out of order", column);
            },
        }
        var n: code.Node = .{ .kind = .repeat, .child = base, .lower = lower, .upper = upper };
        if (p.peek() == '?') { p.p += 1; n.mode = .lazy; } else if (p.peek() == '+') { p.p += 1; n.mode = .possessive; }
        if (quantifier(p.peek())) return p.fail("nested quantifier", p.p + 1);
        return p.node(n);
    }
    fn group(p: *Parser) anyerror!*code.Node {
        const column = p.p + 1; p.p += 1; var special: u8 = 0; var named: ?Text = null;
        if (p.peek() == '?') {
            p.p += 1; special = p.peek(); if (std.mem.indexOfScalar(u8, ":=!<", special) == null or special == 0) return p.fail("invalid group", column); p.p += 1;
            if (special == '<') { const nc = p.p + 1; named = try p.name(); for (p.names.items) |n| if (std.mem.eql(u8, n.name, named.?)) return p.fail("duplicate group name", nc); }
        }
        var number: usize = 0;
        if (special == 0 or special == '<') { p.groups += 1; number = p.groups; if (named) |n| try p.names.append(p.a, .{ .name = n, .group = number }); }
        const content = try p.alternate(); if (p.peek() != ')') return p.fail("missing )", column); p.p += 1;
        if (special == ':') return content;
        if (special == '=' or special == '!') return p.node(.{ .kind = .look, .neg = special == '!', .child = content });
        return p.node(.{ .kind = .group, .value = number, .child = content });
    }
    const Item = struct { set: chars.Set, single: ?u8 };
    fn item(p: *Parser) !Item {
        var c = p.peek(); p.p += 1; var set = chars.Set.initEmpty();
        if (c == '\\') {
            const column = p.p; c = p.peek(); if (c == 0) return p.fail("trailing backslash", column); p.p += 1;
            if (std.mem.indexOfScalar(u8, "dDwWsS", c) != null) { set = chars.standard(c); if (std.ascii.isUpper(c)) set.toggleAll(); return .{ .set = set, .single = null }; }
            if (c == 'n') c = 10 else if (c == 't') c = 9 else if (std.ascii.isAlphanumeric(c)) return p.fail("invalid escape", column);
        }
        set.set(c); return .{ .set = set, .single = c };
    }
    fn characterClass(p: *Parser) !*code.Node {
        const column = p.p + 1; p.p += 1; const neg = p.peek() == '^'; if (neg) p.p += 1;
        if (p.peek() == ']') return p.fail("empty class", p.p + 1);
        var set = chars.Set.initEmpty();
        while (true) {
            if (p.peek() == 0) return p.fail("missing ]", column); if (p.peek() == ']') { p.p += 1; break; }
            const first = try p.item();
            if (p.peek() == '-' and p.p + 1 < p.text.len and p.text[p.p + 1] != ']') {
                const dash = p.p + 1; p.p += 1; if (first.single == null) return p.fail("invalid range", dash); const last = try p.item();
                if (last.single == null or first.single.? > last.single.?) return p.fail("invalid range", dash);
                for (first.single.?..@as(usize, last.single.?) + 1) |c| set.set(c);
            } else set.setUnion(first.set);
        }
        return p.node(.{ .kind = .class, .set = set, .neg = neg });
    }
    fn escape(p: *Parser) !*code.Node {
        const column = p.p + 1; p.p += 1; var c = p.peek(); if (c == 0) return p.fail("trailing backslash", column); p.p += 1;
        if (std.mem.indexOfScalar(u8, "dDwWsS", c) != null) return p.node(.{ .kind = .class, .set = chars.standard(c), .neg = std.ascii.isUpper(c) });
        if (c == 'b' or c == 'B') return p.node(.{ .kind = .assertion, .value = @intFromEnum(if (c == 'b') chars.Assertion.WORD else chars.Assertion.NOTWORD) });
        if ((c >= '1' and c <= '9') or c == 'k') {
            var n: code.Node = .{ .kind = .backref, .column = column };
            if (c == 'k') { if (p.peek() != '<') return p.fail("invalid escape", column); p.p += 1; n.name = try p.name(); }
            else { const start = p.p - 1; _ = p.digits(); n.value = try std.fmt.parseInt(usize, p.text[start..p.p], 10); }
            const result = try p.node(n); try p.refs.append(p.a, result); return result;
        }
        if (c == 'n') c = 10 else if (c == 't') c = 9 else if (std.ascii.isAlphanumeric(c)) return p.fail("invalid escape", column);
        return p.node(.{ .kind = .literal, .value = c });
    }
    fn element(p: *Parser) anyerror!*code.Node {
        const c = p.peek(); switch (c) { '(' => return p.group(), '[' => return p.characterClass(), '\\' => return p.escape(), else => {} }
        p.p += 1; return p.node(switch (c) { '.' => .{ .kind = .any }, '^' => .{ .kind = .assertion, .value = @intFromEnum(chars.Assertion.BOL) }, '$' => .{ .kind = .assertion, .value = @intFromEnum(chars.Assertion.EOL) }, else => .{ .kind = .literal, .value = c } });
    }
